DECLARE use_key text; u finance_journal_uses%ROWTYPE; actual jsonb; audit_count integer;
BEGIN
  use_key:=CASE WHEN TG_TABLE_NAME='finance_journal_uses' THEN NEW.journal_use_id ELSE NEW.journal_use_id END;
  SELECT * INTO STRICT u FROM finance_journal_uses WHERE journal_use_id=use_key;
  IF u.apply_xid=pg_current_xact_id_if_assigned() THEN
    actual:=finance_journal_use_plan(u.vat_use_id);
    PERFORM finance_journal_use_require(actual=u.plan_json,'Journal use stored plan agreement failed');
  END IF;
  IF TG_TABLE_NAME='finance_journal_use_releases' THEN PERFORM finance_journal_use_require(NEW.release_xid=pg_current_xact_id(),'Journal release agreement failed'); END IF;
  IF TG_TABLE_NAME='finance_journal_use_releases' THEN
    SELECT count(*) INTO audit_count FROM audit_log a
    WHERE a.action='finance_journal_use' AND a.target_table='finance_journal_uses'
      AND a.target_id=use_key AND a.actor_user_id=NEW.actor_user_id
      AND a.after_json->>'status'='released' AND a.after_json->>'releaseId'=NEW.release_id;
  ELSE
    SELECT count(*) INTO audit_count FROM audit_log a
    WHERE a.action='finance_journal_use' AND a.target_table='finance_journal_uses'
      AND a.target_id=use_key AND a.actor_user_id=u.actor_user_id
      AND a.after_json->>'status'='applied' AND a.after_json->>'journalUseId'=use_key;
  END IF;
  PERFORM finance_journal_use_require(audit_count=1,'Journal use audit agreement failed');
  RETURN NULL;
END

DECLARE previous finance_journal_use_requests%ROWTYPE; plan jsonb; use_key text; item jsonb; result jsonb;
BEGIN
  SELECT * INTO previous FROM finance_journal_use_requests WHERE request_id=p_request;
  IF FOUND THEN
    PERFORM finance_journal_use_require(previous.action='apply' AND previous.actor_user_id=p_actor AND previous.payload_hash=p_payload_hash,'Journal use request identity mismatch');
    RETURN previous.result_json||jsonb_build_object('replayed',true);
  END IF;
  PERFORM finance_journal_use_lock();
  plan:=finance_journal_use_plan(p_vat_use);
  IF EXISTS(SELECT 1 FROM fiscal_closings c WHERE c.status='closed' AND c.fiscal_year BETWEEN left(plan->>'periodFrom',4)::integer AND left(plan->>'periodTo',4)::integer) THEN
    RAISE EXCEPTION 'Journal use period is closed' USING ERRCODE='23514',CONSTRAINT='finance_journal_use_period_closed';
  END IF;
  PERFORM finance_journal_use_require(plan->>'planHash'=p_expected_hash,'Journal use preview changed');
  PERFORM finance_journal_use_require(NOT EXISTS(SELECT 1 FROM finance_journal_uses WHERE vat_use_id=p_vat_use),'VAT use already has a journal use');
  use_key:='juse-'||finance_document_hash(jsonb_build_array(p_vat_use,p_request,p_actor));
  INSERT INTO finance_journal_uses(journal_use_id,vat_use_id,confirmation_id,return_id,basis_snapshot_id,subject_id,taxpayer_key,period_from,period_to,schema_version,plan_json,plan_hash,request_id,actor_user_id)
  VALUES(use_key,p_vat_use,plan->>'confirmationId',plan->>'returnId',plan->>'basisSnapshotId',plan->>'subjectId',plan->>'taxpayerKey',plan->>'periodFrom',plan->>'periodTo','finance-journal-use-v1',plan,plan->>'planHash',p_request,p_actor);
  FOR item IN SELECT value FROM jsonb_array_elements(plan->'entries') LOOP
    INSERT INTO finance_journal_use_entries(journal_use_id,effect_no,card_source_id,representative_source_id,entry_id,entry_projection,projection_hash,source_hash)
    VALUES(use_key,(item->>'effectNo')::integer,item->>'cardSourceId',item->>'representativeSourceId',item->>'entryId',item->'entryProjection',item->>'projectionHash',item->>'sourceHash');
  END LOOP;
  result:=jsonb_build_object('journalUseId',use_key,'vatUseId',p_vat_use,'status','applied','planHash',p_expected_hash,'replayed',false);
  INSERT INTO finance_journal_use_requests(request_id,action,payload_hash,result_json,actor_user_id) VALUES(p_request,'apply',p_payload_hash,result,p_actor);
  RETURN result;
END

DECLARE state jsonb;
BEGIN
  state:=finance_journal_use_state(p_journal_use);
  PERFORM finance_journal_use_require(state->>'status' IN('applied','released'),'Journal use source or journal changed');
  RETURN state;
END

DECLARE result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'version','finance-journal-entry-projection-v1',
    'entry',to_jsonb(e),
    'lines',COALESCE((SELECT jsonb_agg(to_jsonb(l) ORDER BY l.line_no,l.line_id) FROM journal_lines l WHERE l.entry_id=e.entry_id),'[]'::jsonb),
    'sourceSnapshot',(SELECT to_jsonb(s) FROM journal_source_snapshots s WHERE s.entry_id=e.entry_id)
  ) INTO result FROM journal_entries e WHERE e.entry_id=p_entry;
  RETURN result;
END

BEGIN
  PERFORM finance_journal_use_lock();
  IF TG_TABLE_NAME='finance_journal_uses' THEN PERFORM finance_journal_use_require(NEW.apply_xid=pg_current_xact_id(),'Journal use transaction mismatch'); END IF;
  IF TG_TABLE_NAME='finance_journal_use_releases' THEN PERFORM finance_journal_use_require(NEW.release_xid=pg_current_xact_id(),'Journal release transaction mismatch'); END IF;
  RETURN NEW;
END

BEGIN
  PERFORM pg_advisory_xact_lock(1296256326,1);
  PERFORM finance_vat_use_lock();
  UPDATE finance_journal_use_fence SET generation=generation+1 WHERE fence_id=1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Journal use fence unavailable' USING ERRCODE='55000'; END IF;
END

DECLARE u finance_vat_use_consumptions%ROWTYPE; r record; effect record; e record;
  projection jsonb; items jsonb:='[]'::jsonb; plan jsonb; debit_total numeric; credit_total numeric;
  vat_debit numeric; vat_credit numeric; payable_debit numeric; payable_credit numeric;
  supply_debit numeric; supply_credit numeric; invalid_supply_lines integer; count_cards integer:=0;
BEGIN
  SELECT * INTO STRICT u FROM finance_vat_use_consumptions WHERE use_id=p_vat_use;
  PERFORM finance_vat_use_assert_confirmation(u.confirmation_id);
  SELECT v.form_json,v.return_id,v.basis_snapshot_id,
         v.form_json#>>'{period,from}' period_from,v.form_json#>>'{period,to}' period_to
    INTO STRICT r FROM vat_filing_return_revisions v WHERE v.return_id=u.return_id;
  PERFORM finance_vat_use_assert_current(r.form_json);
  PERFORM finance_journal_use_require(r.period_from ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' AND r.period_to ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$','Journal use filing period unavailable');
  FOR effect IN SELECT effect_no,effect_json FROM finance_vat_use_effects WHERE use_id=p_vat_use AND source_type='card' ORDER BY effect_no LOOP
    count_cards:=count_cards+1;
    SELECT * INTO e FROM journal_entries WHERE source_kind='card' AND source_id=effect.effect_json->>'sourceId';
    PERFORM finance_journal_use_require(FOUND AND e.status='confirmed','Journal use requires an existing confirmed card journal');
    projection:=finance_journal_use_entry_projection(e.entry_id);
    PERFORM finance_journal_use_require(projection->'sourceSnapshot' IS NOT NULL AND projection#>>'{sourceSnapshot,source_hash}' ~ '^[0-9a-f]{64}$','Journal use source snapshot unavailable');
    SELECT COALESCE(sum(l.debit),0),COALESCE(sum(l.credit),0),
      COALESCE(sum(l.debit) FILTER(WHERE l.account_code='135'),0),
      COALESCE(sum(l.credit) FILTER(WHERE l.account_code='135'),0),
      COALESCE(sum(l.debit) FILTER(WHERE l.account_code='253'),0),
      COALESCE(sum(l.credit) FILTER(WHERE l.account_code='253'),0),
      COALESCE(sum(l.debit) FILTER(WHERE l.account_code NOT IN('135','253')),0),
      COALESCE(sum(l.credit) FILTER(WHERE l.account_code NOT IN('135','253')),0),
      count(*) FILTER(WHERE l.account_code NOT IN('135','253') AND NOT finance_journal_use_supply_account(l.account_code))
      INTO debit_total,credit_total,vat_debit,vat_credit,payable_debit,payable_credit,
           supply_debit,supply_credit,invalid_supply_lines
      FROM journal_lines l JOIN journal_accounts a USING(account_code) WHERE l.entry_id=e.entry_id;
    PERFORM finance_journal_use_require(
      debit_total=credit_total AND debit_total=(effect.effect_json->>'rawTotalAmount')::numeric
      AND vat_debit=(effect.effect_json->>'rawTaxAmount')::numeric
      AND vat_credit=0 AND payable_debit=0
      AND payable_credit=(effect.effect_json->>'rawTotalAmount')::numeric
      AND supply_debit=(effect.effect_json->>'rawSupplyAmount')::numeric
      AND supply_credit=0 AND invalid_supply_lines=0,
      'Journal use accounting amount mismatch');
    PERFORM finance_journal_use_require(e.entry_date=effect.effect_json->>'sourceDate' AND e.entry_date BETWEEN r.period_from AND r.period_to,'Journal use accounting date mismatch');
    PERFORM finance_journal_use_require(NOT EXISTS(
      SELECT 1 FROM transaction_invoice_recognitions x WHERE x.source_id=effect.effect_json->>'representativeSourceId'
    ) AND NOT EXISTS(
      SELECT 1 FROM journal_entries x WHERE x.source_id=effect.effect_json->>'representativeSourceId' AND x.source_kind IN('hometax_invoice','tax_invoice')
    ),'Representative invoice already has a separate accounting recognition');
    items:=items||jsonb_build_array(jsonb_build_object(
      'effectNo',effect.effect_no,'cardSourceId',effect.effect_json->>'sourceId',
      'representativeSourceId',effect.effect_json->>'representativeSourceId',
      'entryId',e.entry_id,'entryProjection',projection,
      'projectionHash',finance_document_hash(projection),
      'sourceHash',projection#>>'{sourceSnapshot,source_hash}',
      'supply',(effect.effect_json->>'rawSupplyAmount')::numeric,
      'tax',(effect.effect_json->>'rawTaxAmount')::numeric,
      'total',(effect.effect_json->>'rawTotalAmount')::numeric,
      'accountingDate',e.entry_date));
  END LOOP;
  PERFORM finance_journal_use_require(count_cards BETWEEN 1 AND 200,'Journal use card set unavailable');
  plan:=jsonb_build_object('version','finance-journal-use-plan-v1','vatUseId',u.use_id,
    'confirmationId',u.confirmation_id,'returnId',u.return_id,'basisSnapshotId',u.basis_snapshot_id,
    'subjectId',u.subject_id,'taxpayerKey',u.taxpayer_key,'periodFrom',r.period_from,'periodTo',r.period_to,
    'entries',items);
  RETURN plan||jsonb_build_object('planHash',finance_document_hash(plan));
EXCEPTION WHEN no_data_found THEN
  RAISE EXCEPTION 'Journal use source unavailable' USING ERRCODE='23514',CONSTRAINT='finance_journal_use';
END

DECLARE previous finance_journal_use_requests%ROWTYPE; u finance_journal_uses%ROWTYPE; release_key text; result jsonb; state jsonb;
BEGIN
  SELECT * INTO previous FROM finance_journal_use_requests WHERE request_id=p_request;
  IF FOUND THEN
    PERFORM finance_journal_use_require(previous.action='release' AND previous.actor_user_id=p_actor AND previous.payload_hash=p_payload_hash,'Journal use request identity mismatch');
    RETURN previous.result_json||jsonb_build_object('replayed',true);
  END IF;
  PERFORM finance_journal_use_lock();
  SELECT * INTO STRICT u FROM finance_journal_uses WHERE journal_use_id=p_journal_use FOR UPDATE;
  PERFORM finance_journal_use_require(NOT EXISTS(SELECT 1 FROM finance_journal_use_releases WHERE journal_use_id=p_journal_use),'Journal use already released');
  IF EXISTS(SELECT 1 FROM fiscal_closings c WHERE c.status='closed' AND c.fiscal_year BETWEEN left(u.period_from,4)::integer AND left(u.period_to,4)::integer) THEN
    RAISE EXCEPTION 'Closed fiscal year must be reopened before journal use release' USING ERRCODE='23514',CONSTRAINT='finance_journal_use_period_closed';
  END IF;
  state:=finance_journal_use_state(p_journal_use);
  PERFORM finance_journal_use_require(state->>'status' IN('applied','stale'),'Journal use state cannot be released');
  release_key:='jrel-'||finance_document_hash(jsonb_build_array(p_journal_use,p_request,p_actor,p_reason));
  INSERT INTO finance_journal_use_releases(release_id,journal_use_id,request_id,reason,actor_user_id) VALUES(release_key,p_journal_use,p_request,p_reason,p_actor);
  result:=jsonb_build_object('journalUseId',p_journal_use,'vatUseId',u.vat_use_id,'releaseId',release_key,'status','released','planHash',u.plan_hash,
    'releaseSourceStatus',state->>'status','replayed',false);
  INSERT INTO finance_journal_use_requests(request_id,action,payload_hash,result_json,actor_user_id) VALUES(p_request,'release',p_payload_hash,result,p_actor);
  RETURN result;
END

BEGIN
  IF ok IS DISTINCT FROM true THEN
    RAISE EXCEPTION '%',message USING ERRCODE='23514',CONSTRAINT='finance_journal_use';
  END IF;
END

DECLARE entry_key text; source_key text; account_key text; year_key integer; active_use record; state jsonb;
BEGIN
  IF TG_TABLE_NAME='journal_entries' THEN entry_key:=COALESCE(OLD.entry_id,NEW.entry_id);
  ELSIF TG_TABLE_NAME IN('journal_lines','journal_source_snapshots') THEN entry_key:=COALESCE(OLD.entry_id,NEW.entry_id);
  ELSIF TG_TABLE_NAME='transaction_invoice_recognitions' THEN source_key:=COALESCE(OLD.source_id,NEW.source_id);
  ELSIF TG_TABLE_NAME='journal_accounts' THEN account_key:=COALESCE(OLD.account_code,NEW.account_code);
  ELSIF TG_TABLE_NAME='fiscal_closings' THEN year_key:=COALESCE(OLD.fiscal_year,NEW.fiscal_year); END IF;
  IF entry_key IS NOT NULL AND EXISTS(SELECT 1 FROM finance_journal_use_entries e LEFT JOIN finance_journal_use_releases x USING(journal_use_id) WHERE e.entry_id=entry_key AND x.release_id IS NULL) THEN
    RAISE EXCEPTION 'Journal is in active exact use; release it first' USING ERRCODE='23514',CONSTRAINT='finance_journal_use_source';
  END IF;
  IF source_key IS NOT NULL AND EXISTS(SELECT 1 FROM finance_journal_use_entries e LEFT JOIN finance_journal_use_releases x USING(journal_use_id) WHERE e.representative_source_id=source_key AND x.release_id IS NULL) THEN
    RAISE EXCEPTION 'Representative invoice already uses card journals' USING ERRCODE='23514',CONSTRAINT='finance_journal_use_source';
  END IF;
  IF account_key IS NOT NULL AND EXISTS(SELECT 1 FROM finance_journal_use_entries e JOIN LATERAL jsonb_array_elements(e.entry_projection->'lines') l ON true LEFT JOIN finance_journal_use_releases x USING(journal_use_id) WHERE l->>'account_code'=account_key AND x.release_id IS NULL) THEN
    RAISE EXCEPTION 'Account is referenced by active exact journal use' USING ERRCODE='23514',CONSTRAINT='finance_journal_use_source';
  END IF;
  IF TG_TABLE_NAME='fiscal_closings' THEN
    IF TG_OP<>'DELETE' AND NEW.status='closed' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'closed') THEN
      FOR active_use IN SELECT u.journal_use_id FROM finance_journal_uses u LEFT JOIN finance_journal_use_releases x USING(journal_use_id)
        WHERE year_key BETWEEN left(u.period_from,4)::integer AND left(u.period_to,4)::integer AND x.release_id IS NULL LOOP
        state:=finance_journal_use_state(active_use.journal_use_id);
        IF state->>'status'<>'applied' THEN
          RAISE EXCEPTION 'Stale exact journal use must be resolved before fiscal closing' USING ERRCODE='23514',CONSTRAINT='finance_journal_use_stale_closing';
        END IF;
      END LOOP;
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END

BEGIN
  IF EXISTS(SELECT 1 FROM finance_journal_uses u LEFT JOIN finance_journal_use_releases x USING(journal_use_id) WHERE x.release_id IS NULL) THEN
    RAISE EXCEPTION 'Active exact journal use prevents source truncation' USING ERRCODE='23514',CONSTRAINT='finance_journal_use_source';
  END IF;
  RETURN NULL;
END

DECLARE u finance_journal_uses%ROWTYPE; current_plan jsonb; diagnostic text;
BEGIN
  SELECT * INTO STRICT u FROM finance_journal_uses WHERE journal_use_id=p_journal_use;
  IF EXISTS(SELECT 1 FROM finance_journal_use_releases WHERE journal_use_id=p_journal_use) THEN
    RETURN jsonb_build_object('journalUseId',p_journal_use,'status','released','planHash',u.plan_hash);
  END IF;
  BEGIN
    current_plan:=finance_journal_use_plan(u.vat_use_id);
    IF current_plan=u.plan_json THEN
      RETURN jsonb_build_object('journalUseId',p_journal_use,'status','applied','planHash',u.plan_hash);
    END IF;
    diagnostic:='저장 뒤 원천 또는 전표가 변경되어 현재 근거와 일치하지 않습니다.';
  EXCEPTION
    WHEN check_violation OR no_data_found OR invalid_text_representation OR numeric_value_out_of_range THEN
      diagnostic:='저장 뒤 원천 또는 전표 상태가 변경되어 현재 근거를 재현할 수 없습니다.';
  END;
  RETURN jsonb_build_object('journalUseId',p_journal_use,'status','stale','planHash',u.plan_hash,
    'diagnosticCode','journal_use_source_stale','diagnosticMessage',diagnostic);
END

