      COALESCE(sum(l.debit) FILTER(WHERE l.account_code=''253''),0),
      COALESCE(sum(l.credit) FILTER(WHERE l.account_code=''253''),0),
      COALESCE(sum(l.debit) FILTER(WHERE l.account_code NOT IN(''135'',''253'')),0),
      COALESCE(sum(l.credit) FILTER(WHERE l.account_code NOT IN(''135'',''253'')),0),
      count(*) FILTER(WHERE l.account_code NOT IN(''135'',''253'') AND NOT finance_journal_use_supply_account(l.account_code))
      INTO debit_total,credit_total,vat_debit,vat_credit,payable_debit,payable_credit,
           supply_debit,supply_credit,invalid_supply_lines
