      ''supply'',(effect.effect_json->>''rawSupplyAmount'')::numeric,
      ''tax'',(effect.effect_json->>''rawTaxAmount'')::numeric,
      ''total'',(effect.effect_json->>''rawTotalAmount'')::numeric,
      ''accountingDate'',e.entry_date));
  END LOOP;
