DECLARE entry_key text; source_key text; account_key text; year_key integer; active_use record; state jsonb;
BEGIN
  IF TG_TABLE_NAME=''journal_entries'' THEN entry_key:=COALESCE(OLD.entry_id,NEW.entry_id);
  ELSIF TG_TABLE_NAME IN(''journal_lines'',''journal_source_snapshots'') THEN entry_key:=COALESCE(OLD.entry_id,NEW.entry_id);
  ELSIF TG_TABLE_NAME=''transaction_invoice_recognitions'' THEN source_key:=COALESCE(OLD.source_id,NEW.source_id);
  ELSIF TG_TABLE_NAME=''journal_accounts'' THEN account_key:=COALESCE(OLD.account_code,NEW.account_code);
  ELSIF TG_TABLE_NAME=''fiscal_closings'' THEN year_key:=COALESCE(OLD.fiscal_year,NEW.fiscal_year); END IF;
  IF entry_key IS NOT NULL AND EXISTS(SELECT 1 FROM finance_journal_use_entries e LEFT JOIN finance_journal_use_releases x USING(journal_use_id) WHERE e.entry_id=entry_key AND x.release_id IS NULL) THEN
    RAISE EXCEPTION ''Journal is in active exact use; release it first'' USING ERRCODE=''23514'',CONSTRAINT=''finance_journal_use_source'';
  END IF;
  IF source_key IS NOT NULL AND EXISTS(SELECT 1 FROM finance_journal_use_entries e LEFT JOIN finance_journal_use_releases x USING(journal_use_id) WHERE e.representative_source_id=source_key AND x.release_id IS NULL) THEN
    RAISE EXCEPTION ''Representative invoice already uses card journals'' USING ERRCODE=''23514'',CONSTRAINT=''finance_journal_use_source'';
  END IF;
  IF account_key IS NOT NULL AND EXISTS(SELECT 1 FROM finance_journal_use_entries e JOIN LATERAL jsonb_array_elements(e.entry_projection->''lines'') l ON true LEFT JOIN finance_journal_use_releases x USING(journal_use_id) WHERE l->>''account_code''=account_key AND x.release_id IS NULL) THEN
    RAISE EXCEPTION ''Account is referenced by active exact journal use'' USING ERRCODE=''23514'',CONSTRAINT=''finance_journal_use_source'';
  END IF;
  IF TG_TABLE_NAME=''fiscal_closings'' THEN
    IF TG_OP<>''DELETE'' AND NEW.status=''closed'' AND (TG_OP=''INSERT'' OR OLD.status IS DISTINCT FROM ''closed'') THEN
      FOR active_use IN SELECT u.journal_use_id FROM finance_journal_uses u LEFT JOIN finance_journal_use_releases x USING(journal_use_id)
        WHERE year_key BETWEEN left(u.period_from,4)::integer AND left(u.period_to,4)::integer AND x.release_id IS NULL LOOP
        state:=finance_journal_use_state(active_use.journal_use_id);
        IF state->>''status''<>''applied'' THEN
          RAISE EXCEPTION ''Stale exact journal use must be resolved before fiscal closing'' USING ERRCODE=''23514'',CONSTRAINT=''finance_journal_use_stale_closing'';
        END IF;
      END LOOP;
    END IF;
  END IF;
  IF TG_OP=''DELETE'' THEN RETURN OLD; END IF;
  RETURN NEW;
END ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_journal_use_source_truncate_guard","rows":"0","binary":null,"config":null,"result":"trigger","source":"
